/**
 * Lucide-иконки как inline SVG.
 * Использование: zaymi_icon('check', 'w-4 h-4 text-green-600');
 *
 * Источник: https://lucide.dev (MIT)
 */
if (!defined('ABSPATH')) exit;

function zaymi_icon($name, $class = 'w-5 h-5') {
    $icons = zaymi_icons_map();
    $svg = $icons[$name] ?? $icons['help-circle'];
    $cls = esc_attr($class);
    return str_replace(
        '<svg ',
        '<svg class="' . $cls . '" ',
        $svg
    );
}

